# ══════════════════════ Inflected prepositions ══════════════════════
def PQ(p, g, ans, wrong, e, expl, lvl=1):
    return Q(PREP, f'מה הצורה של "{p}" בגוף {g}?', [ans] + wrong, expl, CARD(f"{p} + {g}", e=e), lvl)

