 ROOTQ('מה השורש של המילה "{w}"?', "הִבַּעְנוּ", "נ־ב־ע", ["ב־ע־ע", "ה־ב־ע", "ב־ו־ע"], "💬", "הביע, הבענו – הנ׳ נבלעה בדגש"),
 Q(ROOT, "לאיזו גזרה שייכים הפעלים שבכרטיס?", ["פ״י", "פ״נ", "ל״ה", "ע״ו / ע״י"], "י׳ בתחילת השורש", CARD("ישב, ירד, ילד", e="🔍")),
 BNQ('באיזה בניין המילה "{w}"?', "הודלק", "הופעל", ["הפעיל", "פועל", "נפעל"], "🔥", "הוּ־ בתחילה – הופעל"),
 Q(BIN, "איזו משמעות יש לבניין בכרטיס?", ["פעולה הדדית", "גרימה", "סביל", "פעולה חוזרת"], "התלחשו – זה עם זה", S("השחקנים התלחשו.", e="🤫")),
 MQ('באיזה משקל המילה "{w}"?', "מַזְרֵק", MAKTEL, [MIKTAL, KATAL, KATELET], "💉", "מַזְרֵק – מַקְטֵל: כלי"),
